function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // eye
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();

  // beholder's face
  ctx.beginPath();
  ctx.arc(W/2 + 100 + 20 * Math.sin(t), H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 + 20 * Math.sin(t), H/2 - 40);
  ctx.lineTo(W/2 + 100 + 20 * Math.sin(t), H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 + 20 * Math.sin(t) - 20, H/2);
  ctx.lineTo(W/2 + 100 + 20 * Math.sin(t) + 20, H/2);
  ctx.stroke();

  // beauty
  ctx.beginPath();
  ctx.arc(W/2 - 100 + 20 * Math.cos(t), H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100 + 20 * Math.cos(t), H/2 - 40);
  ctx.lineTo(W/2 - 100 + 20 * Math.cos(t), H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100 + 20 * Math.cos(t) - 20, H/2);
  ctx.lineTo(W/2 - 100 + 20 * Math.cos(t) + 20, H/2);
  ctx.stroke();

  ctx.restore();
}
